    // bugbugbug  need example complement of atributes emulating DMA engine}   DMA_Engine_Desc_t;typedef DMA_Engine_Desc_t   ssIO_DMA_Engine_t;typedef DMA_Engine_Desc_t  *ssIO_DMA_pEngine_t;#define DMA_pEngineNull    ((ssIO_DMA_pEngine_t) NULL)#endif  // SSIO_OPTIN_DMAS#endif  // __SSIO_DMAS_DCL_H